// shouldSkipEmail — ported verbatim from Code.js
// Conservative: skip only when BOTH subject AND body lack any work-order signal.
// False negatives (missing a lead) are worse than false positives.
const email = $input.item.json;
const sender  = String(email.from    || '').toLowerCase();
const subject = String(email.subject || '').toLowerCase();
const body    = String(email.text    || '').substring(0, 500).toLowerCase();

// Auto-reply / bounce patterns
if (subject.indexOf('auto-reply')      !== -1) return [{ json: { skip: true, reason: 'auto-reply subject' } }];
if (subject.indexOf('out of office')   !== -1) return [{ json: { skip: true, reason: 'out of office' } }];
if (subject.indexOf('delivery failed') !== -1) return [{ json: { skip: true, reason: 'delivery failed' } }];
if (subject.indexOf('mailer-daemon')   !== -1) return [{ json: { skip: true, reason: 'mailer-daemon subject' } }];
if (subject.indexOf('undeliverable')   !== -1) return [{ json: { skip: true, reason: 'undeliverable' } }];
if (sender.indexOf('mailer-daemon')    !== -1) return [{ json: { skip: true, reason: 'mailer-daemon sender' } }];
// no-reply except from Lapham (Lapham website@ is a web form sender)
if (sender.indexOf('no-reply') !== -1 && sender.indexOf('lapham') === -1) return [{ json: { skip: true, reason: 'no-reply sender' } }];

// Exact-match admin subjects (not substrings — avoids skipping "thank you for the repair")
const adminSubjects = [
  'thank you', 'thanks!', 'received', 'confirmed', 'invoice',
  'payment', 'receipt', 'statement', 'for rent', 'vacancy',
  'rent ready', 're: re: re:'
];
for (let i = 0; i < adminSubjects.length; i++) {
  if (subject === adminSubjects[i]) return [{ json: { skip: true, reason: 'admin subject: ' + adminSubjects[i] } }];
}

// Work-order signal check — skip ONLY if BOTH subject AND body have no signals
const workOrderSignals = [
  'repair','fix','broken','leak','plumb','electric','hvac',
  'heat','water','window','door','paint','unit','tenant',
  'maintenance','turnover','inspection','work order','schedule',
  'access','lockbox','entry','pest','mold','damage','replace',
  'install','appliance','stove','fridge','toilet','sink','fan',
  'light','outlet','circuit','roof','floor','wall','ceiling'
];

let hasSignal = false;
for (let j = 0; j < workOrderSignals.length; j++) {
  if (subject.indexOf(workOrderSignals[j]) !== -1 || body.indexOf(workOrderSignals[j]) !== -1) {
    hasSignal = true;
    break;
  }
}

if (!hasSignal) return [{ json: { skip: true, reason: 'no work-order signal in subject or body preview' } }];

// Pass through with skip:false — includes original email fields
return [{ json: { skip: false, email: $input.item.json } }];

// Code: Lapham Extraction
// Ports detectLaphamForm() from Code.js verbatim.
// CRITICAL: Lapham forms arrive as FORWARDS from RM/Lapham employees.
// Detection is content-based (the form text).
// requester = the FORWARDING sender's email, never website@laphamcompany.com.

const email   = $('Gmail Trigger').item.json;
const body    = String(email.text    || '');
const subject = String(email.subject || '');
const rawFrom = String(email.from    || '');

// Extract forwarding sender email — this is the requester (the RM/employee who forwarded)
function extractEmail(raw) {
  const m = String(raw).match(/<([^>]+)>/);
  return m ? m[1].toLowerCase() : String(raw).replace(/.*<|>.*/g, '').toLowerCase().trim();
}

const forwardingSenderEmail = extractEmail(rawFrom);
// requesterEmail is the forwarding sender, NOT website@laphamcompany.com
const requesterEmail = forwardingSenderEmail !== 'website@laphamcompany.com'
  ? forwardingSenderEmail
  : '';

// Two-format field extractor — same-line AND two-line (Apple Mail forwarded format)
function field(names) {
  for (let i = 0; i < names.length; i++) {
    // Same-line: "Label: Value" or "Label Value"
    const re = new RegExp('(?:^|\\n)' + names[i] + '\\s*:?\\s*([^\\n]+)', 'i');
    const m  = body.match(re);
    if (m && m[1].trim()) return m[1].trim();
    // Two-line: "Label\nValue" (Apple Mail forward rendering)
    const re2 = new RegExp('(?:^|\\n)' + names[i] + '[^\\n]*\\n\\s*([^\\n]+)', 'i');
    const m2  = body.match(re2);
    if (m2 && m2[1].trim()) return m2[1].trim();
  }
  return '';
}

function fieldFromBody(names, targetBody) {
  for (let i = 0; i < names.length; i++) {
    const re  = new RegExp('(?:^|\\n)' + names[i] + '\\s*:?\\s*([^\\n]+)', 'i');
    const m   = targetBody.match(re);
    if (m && m[1].trim()) return m[1].trim();
    const re2 = new RegExp('(?:^|\\n)' + names[i] + '[^\\n]*\\n\\s*([^\\n]+)', 'i');
    const m2  = targetBody.match(re2);
    if (m2 && m2[1].trim()) return m2[1].trim();
  }
  return '';
}

// Handle forwarded body — strip > quote prefixes
let forwardedBody = '';
const fwdIdx = body.indexOf('---------- Forwarded message ---------');
if (fwdIdx !== -1) {
  forwardedBody = body.substring(fwdIdx).replace(/^> ?/gm, '');
}

const tenantName  = field(['Name','Full Name','Submitted By','Your Name','First and Last Name']) || (forwardedBody ? fieldFromBody(['Name','Full Name','Submitted By','Your Name','First and Last Name'], forwardedBody) : '');
const address     = field(['Address','Property Address','Property','Location','Street Address']) || (forwardedBody ? fieldFromBody(['Address','Property Address','Property','Location','Street Address'], forwardedBody) : '');
const unit        = field(['Unit','Unit #','Unit Number','Apt','Apartment','Suite']) || (forwardedBody ? fieldFromBody(['Unit','Unit #','Unit Number','Apt','Apartment','Suite'], forwardedBody) : '');
const phone       = field(['Phone','Phone Number','Mobile','Cell','Mobile Number']) || (forwardedBody ? fieldFromBody(['Phone','Phone Number','Mobile','Cell','Mobile Number'], forwardedBody) : '');
let tenantEmail   = field(['Email','Email Address','Your Email']) || (forwardedBody ? fieldFromBody(['Email','Email Address','Your Email'], forwardedBody) : '');
const prefContact = field(['Preferred Contact','Preferred Contact Method','Contact Method','Best Way to Reach']) || (forwardedBody ? fieldFromBody(['Preferred Contact','Preferred Contact Method','Contact Method','Best Way to Reach'], forwardedBody) : '');
const pets        = field(['Pets','Do you have pets','Pets in Unit','Have Pets']) || (forwardedBody ? fieldFromBody(['Pets','Do you have pets','Pets in Unit','Have Pets'], forwardedBody) : '');
const pteRaw      = field(['Permission to Enter','PTE','Entry Permission','permission to enter']) || (forwardedBody ? fieldFromBody(['Permission to Enter','PTE','Entry Permission','permission to enter'], forwardedBody) : '');
let description   = field(['Description','Issue','Problem','Repair Needed','Request','Details','Message','Please describe in detail the maintenance problem below','Please describe']) || (forwardedBody ? fieldFromBody(['Description','Issue','Problem','Repair Needed','Request','Details','Message','Please describe in detail the maintenance problem below','Please describe'], forwardedBody) : '');

if (!description && forwardedBody) {
  description = forwardedBody.replace(/^[-\s]+Forwarded message[-\s]+/i, '').replace(/^[A-Z][^:]+:.*$/gm, '').replace(/\s+/g, ' ').trim();
}

if (tenantEmail) tenantEmail = tenantEmail.replace(/<mailto:[^>]+>/g, '').trim();

// PTE mapping — exact Lapham radio phrases first
const pteLower = (pteRaw || '').toLowerCase();
let pteGranted = 'Not Applicable';
if      (pteLower.indexOf('permission to enter my dwelling while i am not there') !== -1) pteGranted = 'Yes';
else if (pteLower.indexOf('do not give permission') !== -1 || pteLower.indexOf('without my presence') !== -1) pteGranted = 'No';
else if (pteLower === 'yes' || pteLower === 'y') pteGranted = 'Yes';
else if (pteLower === 'no'  || pteLower === 'n') pteGranted = 'No';

// Pets
const petsLower = (pets || '').toLowerCase();
let tenantHasPets = 'Unknown';
if      (petsLower === 'yes' || petsLower === 'y') tenantHasPets = 'Yes';
else if (petsLower === 'no'  || petsLower === 'n') tenantHasPets = 'No';

// Preferred contact
const prefLower = (prefContact || '').toLowerCase();
let tenantPrefContact = 'Unknown';
if      (prefLower.indexOf('phone') !== -1 || prefLower.indexOf('call') !== -1 || prefLower.indexOf('text') !== -1) tenantPrefContact = 'Phone';
else if (prefLower.indexOf('email') !== -1) tenantPrefContact = 'Email';

// Email type from description + subject
const scanText = ((description || '') + ' ' + (subject || '')).toLowerCase();
let emailType = 'adhoc_workorder';
if      (scanText.indexOf('turnover') !== -1 || scanText.indexOf('move out') !== -1 || scanText.indexOf('move-out') !== -1) emailType = 'turnover';
else if (scanText.indexOf('inspection') !== -1) emailType = 'inspection';

// Service category
let serviceCategory = 'Unknown';
if      (scanText.indexOf('plumbing') !== -1 || scanText.indexOf('leak') !== -1 || scanText.indexOf('drain') !== -1) serviceCategory = 'Plumbing';
else if (scanText.indexOf('electrical') !== -1 || scanText.indexOf('outlet') !== -1 || scanText.indexOf('breaker') !== -1) serviceCategory = 'Electrical';
else if (scanText.indexOf('hvac') !== -1 || scanText.indexOf('cooling') !== -1 || scanText.indexOf('heating') !== -1) serviceCategory = 'HVAC';
else if (scanText.indexOf('carpentry') !== -1 || scanText.indexOf('lock') !== -1) serviceCategory = 'Carpentry';
else if (scanText.indexOf('appliance') !== -1) serviceCategory = 'Appliance';
else if (scanText.indexOf('pest') !== -1 || scanText.indexOf('general') !== -1) serviceCategory = 'General Repair';

return [{ json: {
  emailType,
  senderName:             'Lapham Webform',
  senderEmail:            requesterEmail || 'website@laphamcompany.com',
  senderType:             'PM Office Staff',
  companyName:            'Lapham',
  propertyAddress:        address || 'LOOKUP_BY_SENDER',
  unitNumber:             unit,
  city:                   '',
  leadType:               emailType === 'turnover' ? 'Unit Turnover' : emailType === 'inspection' ? 'Inspection' : 'Unknown',
  serviceCategory,
  urgency:                'Standard',
  description:            description || '(No description — see original email)',
  preferredTiming:        '',
  accessInfo:             '',
  rmName:                 '',
  rmEmail:                requesterEmail,
  requesterEmail:         requesterEmail,
  tenantName,
  tenantPhone:            phone,
  tenantEmail,
  tenantPreferredContact: tenantPrefContact,
  tenantHasPets,
  pteGranted,
  pteNotes:               pteRaw,
  estimateNeeded:         'No',
  isLaphamForm:           true,
  multipleItems:          false,
  itemList:               [],
  subjectLineAddressUsed: false,
  senderLookupNeeded:     !address,
  newContactDetected:     false,
  newContactNotes:        '',
  confidence:             'High',
  confidenceNotes:        'Structured Lapham webform — Gemini bypassed'
}}];

// Code: Build Gemini Payload
// Builds the full prompt + request body for the Gemini parsing API.
// Ported from parseWithGemini() + buildSmartPropertyContext() in Code.js.

const email   = $('Gmail Trigger').item.json;
const from    = String(email.from    || '');
const subject = String(email.subject || '');
const body    = String(email.text    || '').substring(0, 2000);

const KNOWN_SENDERS = `KNOWN SENDERS:
APT Internal: brandon@,keith@,tsegab@,bemenet@ aptmaintenanceinc.com — classify normally
Lapham staff: maintenance@laphamcompany.com, website@laphamcompany.com
turnovers.lapham@gmail.com → turnover
cooneysam@gmail.com → inspection
RMs may use @lapham-rm.com, @gmail.com, or address-based emails — match by property address
Lapham webform: website@laphamcompany.com OR "Submitted values are:" OR "Webform submission from: Maintenance Request" → structured form — extract all tenant fields, then classify emailType by content (turnover/inspection/adhoc_workorder) like any other email`;

const LAPHAM_FORM_FORMAT = `
LAPHAM WEBFORM FIELDS (present when sender is website@laphamcompany.com or body contains "Submitted values are:" or "Webform submission from: Maintenance Request"):
Extract: Name/Address/Unit/Phone/Email/PreferredContact/Pets/PTE-choice/Description
PTE: Yes="permission to enter my dwelling while I am not there", No="I do not give permission to enter without my presence", N/A=turnover/inspection
Still classify emailType by work content — turnover, inspection, or adhoc_workorder. Do NOT use "lapham_form" as emailType.`;

const JSON_SCHEMA = `{"emailType":"adhoc_workorder|turnover|inspection|new_inquiry|internal_forward|unknown","senderName":"","senderEmail":"","senderType":"Resident Manager|PM Office Staff|APT Internal|Unknown","companyName":"","propertyAddress":"","unitNumber":"","city":"","leadType":"Urgent Repair|Unit Turnover|Recurring Maintenance|Quote Request|Inspection|New Client Inquiry|Unknown","serviceCategory":"Plumbing|Electrical|Carpentry|Painting|HVAC|Appliance|Junk Removal|Windows|General Repair|Multi-trade|Renovation|Unknown","urgency":"Urgent|Standard|Flexible","description":"1-2 sentence plain trade language","preferredTiming":"","accessInfo":"","rmName":"","rmEmail":"","tenantName":"","tenantPhone":"","tenantEmail":"","tenantPreferredContact":"Phone|Email|Unknown","tenantHasPets":"Yes|No|Unknown","pteGranted":"Yes|No|Not Applicable","pteNotes":"","isLaphamForm":false,"multipleItems":false,"itemList":[],"estimateNeeded":"Yes|No|Unknown (Yes=quote request/renovation/multi-trade/scope unclear. No=standard repair with defined scope)","subjectLineAddressUsed":false,"senderLookupNeeded":false,"newContactDetected":false,"newContactNotes":"","confidence":"High|Medium|Low","confidenceNotes":""}`;

const prompt = `You are a work order intake agent for APT Maintenance (Bay Area property maintenance).
Parse emails to workorder@aptmaintenanceinc.com. Extract structured data. Return ONLY raw JSON.

${KNOWN_SENDERS}

${LAPHAM_FORM_FORMAT}

FROM: ${from}
SUBJECT: ${subject}

THREAD:
${body}

RULES: Scan full thread. Extract address from subject if not in body. If no address found set propertyAddress=LOOKUP_BY_SENDER. Urgency: Urgent=active leak/sewage/no heat/no electricity/flooding/fire/word 'emergency' ONLY. Standard=most repairs. Flexible=quotes/turnovers/inspections. Never Urgent for frustration alone.

Return ONLY this JSON (no markdown, no backticks):
${JSON_SCHEMA}`;

return [{
  json: {
    geminiPayload: {
      contents: [{ parts: [{ text: prompt }] }],
      generationConfig: { temperature: 0.1, maxOutputTokens: 2048 }
    },
    _originalFrom: from
  }
}];

// Parse Gemini Response — 4-strategy extractJson chain from Code.js
const response = $input.item.json;
const rawText  = response.candidates &&
                 response.candidates[0] &&
                 response.candidates[0].content &&
                 response.candidates[0].content.parts &&
                 response.candidates[0].content.parts[0]
                 ? response.candidates[0].content.parts[0].text : '';

if (!rawText) {
  return [{ json: { parsedForm: null, parseError: 'Gemini returned empty text' } }];
}

// 4-strategy extractJson chain — verbatim from Code.js
function extractJson(text) {
  // Strategy 1: direct parse
  try { return JSON.parse(text.trim()); } catch(e) {}
  // Strategy 2: strip markdown code fences
  const m = text.match(/```(?:json)?\s*([\s\S]*?)```/i);
  if (m) { try { return JSON.parse(m[1].trim()); } catch(e) {} }
  // Strategy 3: find first { to last }
  const start = text.indexOf('{');
  const end   = text.lastIndexOf('}');
  if (start !== -1 && end !== -1 && end > start) {
    try { return JSON.parse(text.substring(start, end + 1)); } catch(e) {}
  }
  // Strategy 4: clean up common LLM JSON issues
  if (start !== -1 && end !== -1) {
    const cleaned = text.substring(start, end + 1)
      .replace(/,\s*([}\]])/g, '$1')
      .replace(/'/g, '"')
      .replace(/:\s*True/g,  ': true')
      .replace(/:\s*False/g, ': false')
      .replace(/:\s*None/g,  ': null');
    try { return JSON.parse(cleaned); } catch(e) {}
  }
  return null;
}

const parsed = extractJson(rawText);
if (!parsed) {
  return [{ json: { parsedForm: null, parseError: 'JSON extract failed', rawText: rawText.substring(0, 300) } }];
}

// Strip <mailto:...> wrappers from tenant email
if (parsed.tenantEmail) {
  parsed.tenantEmail = parsed.tenantEmail.replace(/^<mailto:|>$/g, '').trim();
}

// Address fallback — LOOKUP_BY_SENDER when Gemini returns nothing useful
if (!parsed.propertyAddress || parsed.propertyAddress === 'Unknown' || parsed.propertyAddress === '') {
  parsed.propertyAddress    = 'LOOKUP_BY_SENDER';
  parsed.senderLookupNeeded = true;
}

return [{ json: { parsedForm: parsed } }];

// Normalize address key for Neon property lookup.
// Verbatim port of normalizeAddressKey() from Code.js (7-step algorithm).

const incoming = $input.item.json;

// Accept both Lapham (direct parsedForm fields) and Gemini (wrapped in parsedForm)
const parsedForm = incoming.isLaphamForm
  ? incoming
  : (incoming.parsedForm || incoming);

function normalizeAddressKey(address, unit) {
  // Step 1: ## → #
  let addr = String(address || '').replace(/##/g, '#');
  // Step 2: extract embedded unit (#word) when unit param absent/empty
  const embeddedUnit = addr.match(/#(\w+)/);
  if (embeddedUnit && !unit) unit = embeddedUnit[1];
  // Step 3: strip #\w+ from address
  addr = addr.replace(/#\w+/g, '').trim();
  // Step 4: strip city/state suffix
  addr = addr.split(',')[0].trim();
  // Step 5: normalize street-type tokens (lowercase + strip trailing period)
  addr = addr.replace(/\b(avenue|ave|street|st|boulevard|blvd|drive|dr|road|rd|lane|ln|way|place|pl|court|ct|terrace|terr)\b\.?/gi, m => m.replace(/\.$/, '').toLowerCase());
  // Step 6: lowercase, strip non-alphanumeric, collapse spaces
  addr = addr.toLowerCase().replace(/[^a-z0-9\s]/g, '').replace(/\s+/g, ' ').trim();
  const unitNorm = String(unit || '').toLowerCase().replace(/[^a-z0-9]/g, '').trim();
  // Step 7: composite key
  return addr + '||' + unitNorm;
}

const addressKey = normalizeAddressKey(
  parsedForm.propertyAddress || '',
  parsedForm.unitNumber || ''
);

return [{ json: { ...parsedForm, addressKey } }];

// Merge property data from Neon lookup into parsed form.
// Mirrors enrichFromLaphamDb() from Code.js — two strategies: address-first, then sender-email fallback.
// Access info: merge-not-replace (Neon DB is authoritative; inbound may add context).

const parsedForm   = $('Code: Normalize Address Key').item.json;
const neonRows     = $input.all().map(item => item.json);
const record       = neonRows.length > 0 ? neonRows[0] : null;

function extractCodes(text) {
  if (!text) return [];
  const matches = String(text).match(/\b\d{3,6}\b/g) || [];
  return matches.filter((m, i, arr) => arr.indexOf(m) === i);
}

let merged = { ...parsedForm };

if (record && record.id) {
  // Address-first match or email fallback — enrich the parsed form
  merged.rmName        = merged.rmName  || record.rm_name  || '';
  merged.rmEmail       = merged.rmEmail || record.rm_email || '';
  merged.propertyKnown = true;

  // If lookup used sender-email fallback and address was LOOKUP_BY_SENDER, fill in from DB
  if (!merged.propertyAddress || merged.propertyAddress === 'LOOKUP_BY_SENDER') {
    merged.propertyAddress    = record.address || merged.propertyAddress;
    merged.senderLookupNeeded = false;
  }

  // Access info change detection (from enrichFromLaphamDb in Code.js)
  const existingCodes = extractCodes(record.access_info || '');
  const newCodes      = extractCodes(merged.accessInfo   || '');
  const trulyNew      = newCodes.filter(c => !existingCodes.includes(c));

  if (trulyNew.length > 0 && merged.accessInfo) {
    merged.accessInfoChanged  = true;
    merged.accessInfoNew      = merged.accessInfo;
    merged.accessInfoExisting = record.access_info || '';
  }

  // Merge access info — DB first, email appended (never replace)
  if (record.access_info && merged.accessInfo) {
    merged.accessInfo = record.access_info + ' | ' + merged.accessInfo;
  } else {
    merged.accessInfo = record.access_info || merged.accessInfo || '';
  }
} else {
  merged.propertyKnown = false;
  if (merged.propertyAddress &&
      merged.propertyAddress !== 'LOOKUP_BY_SENDER' &&
      merged.propertyAddress !== 'Unknown') {
    merged.newContactDetected = true;
    merged.newContactNotes    = merged.newContactNotes || 'Property not in Neon properties table.';
  }
}

merged._neonPropertyId = record ? record.id : null;

// ---------------------------------------------------------------------------
// jobs/sync payload — explicit column mapping (raw merged blob is NOT a valid
// jobs row and has no jobId; the route 400s without one).
// jobId is DETERMINISTIC from the Gmail message id: the same email re-delivered
// or re-processed produces the same jobId, and the jobs/sync upsert
// (onConflictDoUpdate on jobId) absorbs it — this is the dedup mechanism,
// equivalent to GAS processedIds-by-msgId. (GAS isDuplicateJob address+unit
// heuristic intentionally not ported — msgId idempotency is stricter.)
// ---------------------------------------------------------------------------
const gmailMsgId = String($('Gmail Trigger').item.json.id || merged.gmailMsgId || '');
const jobId = 'EMAIL-' + (gmailMsgId || Date.now());

merged.gmailMsgId = gmailMsgId;
merged.jobPayload = {
  orgId:        'APT-CA',
  jobId:        jobId,
  timestamp:    new Date().toISOString(),
  priority:     merged.urgency === 'Urgent' ? '1-URGENT' : '4-STANDARD',
  emailType:    merged.emailType || 'adhoc_workorder',
  category:     merged.serviceCategory || null,
  address:      (merged.propertyAddress && merged.propertyAddress !== 'LOOKUP_BY_SENDER') ? merged.propertyAddress : null,
  unit:         merged.unitNumber || null,
  description:  merged.description || null,
  accessInfo:   merged.accessInfo || null,
  rmName:       merged.rmName || null,
  rmEmail:      merged.rmEmail || null,
  tenantName:   merged.tenantName || null,
  tenantPhone:  merged.tenantPhone || null,
  tenantEmail:  merged.tenantEmail || null,
  tenantPref:   merged.tenantPreferredContact || null,
  tenantPets:   merged.tenantHasPets || null,
  pte:          merged.pteGranted || null,
  status:       'Needs Review',
  notes:        merged.newContactDetected ? (merged.newContactNotes || '') : null,
  gmailMsgId:   gmailMsgId || null,
};

return [{ json: merged }];

